CREATE TABLE financial_commitments (id VARCHAR(36) NOT NULL, owner_id VARCHAR(36) NOT NULL, recurrence_rule_id VARCHAR(36), type VARCHAR(20) NOT NULL, description VARCHAR(255) NOT NULL, planned_amount DECIMAL(19,2) NOT NULL, due_date DATE NOT NULL, account_id VARCHAR(36) NOT NULL, category_id VARCHAR(36) NOT NULL, status VARCHAR(20) NOT NULL, financial_transaction_id VARCHAR(36), settled_at TIMESTAMP(6), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, version BIGINT NULL, PRIMARY KEY(id), CONSTRAINT ck_commitment_amount CHECK(planned_amount > 0), CONSTRAINT ck_commitment_status CHECK(status IN ('PENDING','SETTLED','CANCELLED')), CONSTRAINT uq_commitment_tx UNIQUE(financial_transaction_id), CONSTRAINT uq_commitment_occurrence UNIQUE(owner_id, recurrence_rule_id, due_date), CONSTRAINT fk_commitment_rule FOREIGN KEY(recurrence_rule_id) REFERENCES recurrence_rules(id), CONSTRAINT fk_commitment_account FOREIGN KEY(account_id) REFERENCES asset_accounts(id), CONSTRAINT fk_commitment_category FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE INDEX idx_commitment_owner_due ON financial_commitments(owner_id,due_date);
CREATE INDEX idx_commitment_owner_status ON financial_commitments(owner_id,status);
